output_text:
[
  {
    "id": "no_cart_single_file",
    "text": "Shopping carts are prohibited in single-file product aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "enter_single_file_from_staging",
    "text": "Agents may enter a single-file aisle only from a wide non-shelf staging mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "wideStagingMouth": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "enterSingleFileAisle": {
          "pre": "MOVE",
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "enterSingleFileAisle",
          {
            "not": "wideStagingMouth"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_open_roaming",
    "text": "After leaving a cart behind, cartless movement is allowed only for entering or returning from a single-file aisle, not for roaming through open aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "openAisle": {
          "not": "singleFileAisle"
        }
      },
      "events": {
        "cartlessOpenMoveNotTowardSingleFile": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "openAisle",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              {
                "not": "hasCart"
              },
              "openAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartlessOpenMoveNotTowardSingleFile"
    }
  },
  {
    "id": "reclaim_after_single_file",
    "text": "On returning cartless from a single-file aisle to an open aisle, the agent is obliged to reclaim a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "openAisle": {
          "not": "singleFileAisle"
        }
      },
      "events": {
        "returnCartlessFromSingleFile": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileAisle",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              {
                "not": "hasCart"
              },
              "openAisle"
            ]
          }
        },
        "reclaimCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returnCartlessFromSingleFile",
      "discharge": "reclaimCart"
    }
  },
  {
    "id": "cart_required_open_shelf",
    "text": "Shelf interactions from open or wide aisles must be done while holding the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "openShelfFront": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfFront",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_single_file_shelf",
    "text": "Shelf interactions inside single-file aisles must be done without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "singleFileShelfFront": {
          "and": [
            "singleFileAisle",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "singleFileShelfFront",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "park_only_at_staging_mouth",
    "text": "Carts may be parked only at wide non-shelf staging mouths rather than in shelf-front or narrow spaces.",
    "abstraction": {
      "state_properties": {
        "wideStagingMouth": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "wideStagingMouth"
          }
        ]
      }
    }
  },
  {
    "id": "take_cart_from_bay",
    "text": "Before shopping, the agent is obliged to take a cart from the entrance cart bay.",
    "abstraction": {
      "state_properties": {
        "entranceCartBay": {
          "and": [
            "at(1,7)",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                8
              ]
            }
          ]
        }
      },
      "events": {
        "takeCartFromBay": {
          "pre": {
            "and": [
              "entranceCartBay",
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCartFromBay"
    }
  }
]
